const config = $('Workflow Configuration').first().json;
const sinceTime = new Date(config.SINCE_ISO).getTime();
const untilTime = new Date(config.UNTIL_ISO).getTime();
const lang = (config.LANGUAGE || 'EN').toUpperCase() === 'FR' ? 'FR' : 'EN';

// Helper to normalize items from n8n HTTP Request (handles both flat items and array responses across pages)
function extractItems(nodeName) {
  const raw = $(nodeName).all().map(item => item.json);
  const flat = [];
  for (const entry of raw) {
    if (Array.isArray(entry)) {
      flat.push(...entry);
    } else if (entry && typeof entry === 'object' && Object.keys(entry).length > 0) {
      flat.push(entry);
    }
  }
  return flat;
}

// Optional extra pagination fallback via this.helpers.httpRequest if page 1 hit exactly 100 items
async function fetchAdditionalPages(endpoint, baseQs, currentItems, stopWhenOlderThanSince = false) {
  if (currentItems.length < 100 || typeof this.helpers?.httpRequest !== 'function') {
    return currentItems;
  }
  const allItems = [...currentItems];
  const headers = {
    'Accept': 'application/vnd.github+json',
    'X-GitHub-Api-Version': '2022-11-28',
    'User-Agent': 'n8n-claude-weekly-dev-summary'
  };
  if ($env.GITHUB_TOKEN) {
    headers['Authorization'] = `Bearer ${$env.GITHUB_TOKEN}`;
  }
  for (let page = 2; page <= 10; page++) {
    try {
      const pageData = await this.helpers.httpRequest({
        method: 'GET',
        url: `https://api.github.com/repos/${config.GITHUB_REPO}/${endpoint}`,
        qs: { ...baseQs, per_page: 100, page },
        headers,
        json: true
      });
      if (!Array.isArray(pageData) || pageData.length === 0) break;
      allItems.push(...pageData);
      if (stopWhenOlderThanSince) {
        const lastUpdated = pageData[pageData.length - 1]?.updated_at;
        if (lastUpdated && new Date(lastUpdated).getTime() < sinceTime) break;
      }
      if (pageData.length < 100) break;
    } catch (err) {
      break;
    }
  }
  return allItems;
}

// 1. Process Commits (with multi-page support)
let rawCommits = extractItems('Fetch Weekly Commits').filter(c => c && c.sha);
rawCommits = await fetchAdditionalPages.call(
  this,
  'commits',
  { since: config.SINCE_ISO, until: config.UNTIL_ISO },
  rawCommits,
  false
);
const seenShas = new Set();
const commits = rawCommits.filter(c => {
  if (!c.sha || seenShas.has(c.sha)) return false;
  seenShas.add(c.sha);
  return true;
}).map(c => ({
  sha: c.sha.substring(0, 7),
  message: (c.commit?.message || '').split('\n')[0],
  author: c.commit?.author?.name || c.author?.login || 'unknown',
  date: c.commit?.author?.date || ''
}));

// 2. Process Closed Issues (exclude PRs returned by GitHub's /issues endpoint, with multi-page support)
let rawIssuesAll = extractItems('Fetch Closed Issues').filter(i => i && i.id);
rawIssuesAll = await fetchAdditionalPages.call(
  this,
  'issues',
  { state: 'closed', since: config.SINCE_ISO, sort: 'updated', direction: 'desc' },
  rawIssuesAll,
  true
);
const seenIssues = new Set();
const closedIssues = rawIssuesAll.filter(i => {
  if (!i.id || i.pull_request || seenIssues.has(i.id)) return false;
  seenIssues.add(i.id);
  if (!i.closed_at) return false;
  const closedAt = new Date(i.closed_at).getTime();
  return closedAt >= sinceTime && closedAt <= untilTime;
}).map(i => ({
  number: i.number,
  title: i.title,
  author: i.user?.login || 'unknown',
  labels: (i.labels || []).map(l => l.name).join(', '),
  closed_at: i.closed_at
}));

// 3. Process Merged PRs within the 7-day window (with multi-page support)
let rawPRs = extractItems('Fetch Closed PRs').filter(pr => pr && pr.id);
rawPRs = await fetchAdditionalPages.call(
  this,
  'pulls',
  { state: 'closed', sort: 'updated', direction: 'desc' },
  rawPRs,
  true
);
const seenPRs = new Set();
const mergedPRs = rawPRs.filter(pr => {
  if (!pr.id || seenPRs.has(pr.id)) return false;
  seenPRs.add(pr.id);
  if (!pr.merged_at) return false;
  const mergedAt = new Date(pr.merged_at).getTime();
  return mergedAt >= sinceTime && mergedAt <= untilTime;
}).map(pr => ({
  number: pr.number,
  title: pr.title,
  author: pr.user?.login || 'unknown',
  merged_at: pr.merged_at,
  body_preview: (pr.body || '').replace(/\r?\n/g, ' ').slice(0, 240)
}));

const contributors = Array.from(new Set([
  ...commits.map(c => c.author),
  ...mergedPRs.map(p => p.author),
  ...closedIssues.map(i => i.author)
].filter(Boolean)));

const languageInstruction = lang === 'FR'
  ? 'Write the entire summary in fluent, professional French (Français).'
  : 'Write the entire summary in clear, professional English.';

const systemPrompt = `You are a Principal Engineering Lead producing an automated Weekly Development Summary for a GitHub repository.
${languageInstruction}
Structure the summary into both an Executive and Technical narrative:
1. **Executive Overview**: High-level narrative of velocity, key themes, and user/product impact this week.
2. **Technical Narrative — Shipped Features & Merged PRs**: Detailed walkthrough of major pull requests and architectural changes (reference PR #numbers).
3. **Resolved Issues & Bug Fixes**: Notable bugs squashed and issues closed (reference Issue #numbers).
4. **Commit & Contributor Highlights**: Key commits and active contributors.
5. **Weekly Momentum**: Brief 1-2 sentence outlook.`;

const userPrompt = `Repository: ${config.GITHUB_REPO}
Period: ${config.SINCE_ISO.slice(0, 10)} to ${config.UNTIL_ISO.slice(0, 10)}
Target Language: ${lang}

### Metrics
- Total Commits: ${commits.length}
- Merged PRs: ${mergedPRs.length}
- Closed Issues: ${closedIssues.length}
- Active Contributors (${contributors.length}): ${contributors.join(', ') || 'None'}

### Merged Pull Requests (${mergedPRs.length})
${mergedPRs.length ? mergedPRs.map(p => `- PR #${p.number}: ${p.title} (by @${p.author}) — ${p.body_preview}`).join('\n') : 'No pull requests merged this week.'}

### Closed Issues (${closedIssues.length})
${closedIssues.length ? closedIssues.map(i => `- Issue #${i.number}: ${i.title} (by @${i.author})${i.labels ? ` [${i.labels}]` : ''}`).join('\n') : 'No issues closed this week.'}

### Commits (${commits.length})
${commits.length ? commits.slice(0, 100).map(c => `- \`${c.sha}\` ${c.message} (${c.author})`).join('\n') : 'No commits recorded this week.'}

Please generate the weekly narrative summary now.`;

return [{
  json: {
    config,
    stats: {
      commits: commits.length,
      mergedPRs: mergedPRs.length,
      closedIssues: closedIssues.length,
      contributorsCount: contributors.length
    },
    systemPrompt,
    userPrompt
  }
}];

const aggregated = $('Aggregate Activity & Build Prompt').first().json;
const claudeRes = $('Claude Narrative Summary').first().json;
const config = aggregated.config;
const stats = aggregated.stats;

const narrative = (claudeRes.content && claudeRes.content[0] && claudeRes.content[0].text)
  ? claudeRes.content[0].text
  : 'No summary text returned from Claude API.';

const headerTitle = config.LANGUAGE === 'FR'
  ? `📊 Résumé Hebdomadaire — ${config.GITHUB_REPO} (${config.SINCE_ISO.slice(0, 10)} → ${config.UNTIL_ISO.slice(0, 10)})`
  : `📊 Weekly Dev Summary — ${config.GITHUB_REPO} (${config.SINCE_ISO.slice(0, 10)} → ${config.UNTIL_ISO.slice(0, 10)})`;

const fullMessage = `${headerTitle}\n\n${narrative}`;

// Split long text on paragraph boundaries so no characters are ever truncated
function chunkText(text, maxLen) {
  if (text.length <= maxLen) return [text];
  const chunks = [];
  let remaining = text;
  while (remaining.length > maxLen) {
    let splitIdx = remaining.lastIndexOf('\n\n', maxLen);
    if (splitIdx <= 0) splitIdx = remaining.lastIndexOf('\n', maxLen);
    if (splitIdx <= 0) splitIdx = remaining.lastIndexOf(' ', maxLen);
    if (splitIdx <= 0) splitIdx = maxLen;
    chunks.push(remaining.slice(0, splitIdx).trim());
    remaining = remaining.slice(splitIdx).trim();
  }
  if (remaining.length > 0) chunks.push(remaining);
  return chunks;
}

// Discord embeds allow up to 4096 chars per embed description and up to 6000 chars across embeds
const embedDescriptionChunks = chunkText(narrative, 3900);
const discordEmbeds = embedDescriptionChunks.map((chunk, idx) => ({
  title: idx === 0 ? headerTitle : `${headerTitle} (Part ${idx + 1}/${embedDescriptionChunks.length})`,
  description: chunk,
  color: 14251863,
  ...(idx === embedDescriptionChunks.length - 1 ? {
    fields: [
      { name: 'Commits', value: String(stats.commits), inline: true },
      { name: 'Merged PRs', value: String(stats.mergedPRs), inline: true },
      { name: 'Closed Issues', value: String(stats.closedIssues), inline: true },
      { name: 'Destination', value: String(config.DESTINATION_CHANNEL), inline: true }
    ],
    footer: { text: `Claude (claude-sonnet-4-20250514) • Channel: ${config.DESTINATION_CHANNEL}` },
    timestamp: config.UNTIL_ISO
  } : {})
}));

// Determine target URL & payload shape based on DELIVERY_METHOD and WEBHOOK_URL
const isDiscord = config.DELIVERY_METHOD === 'discord' || (config.WEBHOOK_URL || '').includes('discord.com/api/webhooks');
const isSlackApi = config.DELIVERY_METHOD === 'slack_api' || (config.WEBHOOK_URL || '').includes('slack.com/api/chat.postMessage');

// If Discord and DESTINATION_CHANNEL is a numeric thread ID, route to that thread via ?thread_id=
let resolvedWebhookUrl = config.WEBHOOK_URL || 'https://slack.com/api/chat.postMessage';
if (isDiscord && /^\d+$/.test((config.DESTINATION_CHANNEL || '').trim())) {
  const sep = resolvedWebhookUrl.includes('?') ? '&' : '?';
  resolvedWebhookUrl = `${resolvedWebhookUrl}${sep}thread_id=${config.DESTINATION_CHANNEL.trim()}`;
}

const webhookPayload = isDiscord
  ? {
      username: 'Claude Weekly Dev Digest',
      content: `${headerTitle} (${config.DESTINATION_CHANNEL})`,
      embeds: discordEmbeds
    }
  : {
      channel: config.DESTINATION_CHANNEL,
      username: 'Claude Weekly Dev Digest',
      text: fullMessage,
      mrkdwn: true
    };

return [{
  json: {
    repo: config.GITHUB_REPO,
    destinationChannel: config.DESTINATION_CHANNEL,
    language: config.LANGUAGE,
    deliveryMethod: config.DELIVERY_METHOD,
    webhookUrl: resolvedWebhookUrl,
    isSlackApi,
    stats,
    subject: headerTitle,
    narrative,
    fullMessage,
    contentChunks: chunkText(fullMessage, 1990),
    webhookPayload
  }
}];
